  "claims": [
    {
      "claim": "All L1 gold records report human oral or systemic bioavailability values at or above 22% (labetalol 63±7% in cirrhosis; 5-HTP 49%; pramipexole >90%; PF-05241328 38%; cilomilast 96%; leucovorin 100%; 1,25(OH)2D2 41±18%; AZD0837 22–55%; isradipine 37%; ebastine ~40%).",
      "card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C14"]
    },
    {
      "claim": "L2 records confirm or refine these values and do not reveal any sub-20% value: labetalol 63% (vs 33% controls), 5-HTP mouse F=40%, cilomilast 103%, AZD0837 ~22–55%, isradipine 28–37% in cirrhosis, PF-05241328 38%, 1,25(OH)2D2 43±35%.",
      "card_ids": ["C16","C17","C18","C19","C20","C21","C22","C23","C24"]
    },
    {
      "claim": "The only L2 'low' statement (ebastine, C25) is non-numeric and conflicts with L1 C02 (~40%) and C15 (highly bioavailable); it does not affirm F<20%.",
      "card_ids": ["C25","C02","C15"]
    },
    {
      "claim": "Structurally relevant polar basic/amide-containing molecules (labetalol, 5-HTP, pramipexole) show F≥20%, supporting that the query's ionization and low logD do not by themselves imply F<20%.",
      "card_ids": ["C13","C11","C01"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C15","C16","C17","C18","C19","C20","C21","C22","C23","C24"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C25"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present.",
    "No matched oral-versus-IV exposure data for the query are supplied; transfer relies on structurally and physicochemically related contexts.",
    "First-pass metabolism and possible transporter-mediated absorption for the query are not directly characterized.",
    "The query's very low logD (-1.56) and full ionization at physiological pH leave residual permeability uncertainty not directly resolved by the contexts.",
    "The ebastine 'low' statement (C25) is non-numeric and not threshold-specific."
  ],
  "decision_summary": "L2 records largely confirm the L1 pattern of F ≥ 20% across all transferable contexts, including structurally relevant polar basic/amide molecules; the only non-numeric 'low' statement is not threshold-relevant. The prediction remains high with moderate confidence."
}

